def esc(x):return html.escape(str(x))
def math(x):return r'\('+esc(x)+r'\)'
def n(x):return math(str(x))
def s(x):return math(f'{x:.6f}')

def words(f,m):
    """Translate each ACTUAL displayed formula, not only the inference label."""
    h=f[0]
    if h=='eq':return math(tex(f[1],m))+' equals '+math(tex(f[2],m))
    if h=='not' and f[1][0]=='eq':return math(tex(f[1][1],m))+' differs from '+math(tex(f[1][2],m))
    if h=='not':return 'it is false that ('+words(f[1],m)+')'
    if h=='bot':return 'a contradiction'
    if h=='top':return 'a statement that is always true'
    if h in ('forall','exists'):
        variables=[];body=f
        while body[0]==h:
            variables.append(math(tex(('var',body[1]),m)));body=body[2]
        return ('for every ' if h=='forall' else 'there exist ')+', '.join(variables)+', '+words(body,m)
    if h=='and':return 'both ('+words(f[1],m)+') and ('+words(f[2],m)+') hold'
    if h=='or':return 'at least one of ('+words(f[1],m)+') or ('+words(f[2],m)+') holds'
    if h=='imp':return 'if ('+words(f[1],m)+'), then ('+words(f[2],m)+')'
    raise ValueError('reader formula outside exact equational fragment')

def panel(o,m,text,i,interfaces):
    proof=o['proof_check']['result'];aliases={name:'w_{'+str(k+1)+'}' for k,name in enumerate(proof['introductions'])}
    m={**m,'witness_names':aliases};rs=records(text);numbers={r['name']:k+1 for k,r in enumerate(rs)}
    used=o['used_lemma_inputs'];parts=['<article class="proof-panel" id="proof-'+str(i)+'"'+(' hidden' if i else '')+'>']
    parts.append('<p><strong>'+('Three-instance union theory' if o['kind']=='theory' else 'Same union and complete admitted library')+'</strong> · run '+n(o['repetition'])+' · '+n(len(rs))+' returned lines. '+('No lemma input used.' if not used else 'Used interface: '+', '.join('<code>'+esc(x)+'</code>' for x in used)+'.')+'</p>')
    parts.append('<p class="small">Every display alias in this run is listed below. Unary aliases retain their actual argument; these are separate fresh functions, not geometric placements.</p><table class="alias-table"><thead><tr><th>Display alias</th><th>Actual E name</th><th>Arity</th></tr></thead><tbody>')
    for name,alias in aliases.items():
        parts.append('<tr><td>'+math(alias)+'</td><td><code>'+esc(name)+'</code></td><td>'+n(proof['introductions'][name]['arity'])+'</td></tr>')
    parts.append('</tbody></table>')
    for j,(r,c) in enumerate(zip(rs,proof['checks'])):
        boundary=c['status']=='checked_conservative_context_extension'
        formula=closed(r['formula']);parts.append('<div class="proof-line'+(' boundary' if boundary else '')+'"><span class="line-number">'+n(j+1)+'</span><div><div class="formula">'+math(tex(formula,m))+'</div><p class="translation">'+words(formula,m)+'.</p>')
        if c['status']=='checked_input':
            annotation='Exact supplied '+('conjecture; this target is not an assumed fact.' if r['role']=='conjecture' else 'axiom or admitted interface.')
            if r['name']=='l20':annotation='The admitted induction interface: a base identity for every first parameter and a successor step for every pair imply the universal left-successor identity. Its independent setup certificate precedes E.'
        elif c['status']=='checked_negation':annotation='Assume the universal conclusion is false and seek a contradiction; counterexample objects must exist.'
        elif boundary:annotation='A conservative extension names fresh witnesses with their exact lexical dependencies. This is checked by model expansion, rather than ordinary entailment in the original signature.'
        else:annotation='The displayed formula is independently certified from the earlier parent formulas.'
        ps=c.get('parents',[])
        if ps:annotation+=' Parent rows: '+', '.join(n(numbers[p]) for p in ps)+'.'
        parts.append('<p class="annotation">'+annotation+'</p><p class="small"><code>'+esc(r['name'])+'</code> · '+esc(c['status'])+'</p>')
        if boundary:
            rc=c['reconstruction'];parts.append('<details class="reconstruction"><summary>Inspect the full conservative-extension boundary</summary><p>This explicit replacement derivation certifies the compressed printed annotation. It does not claim to reproduce E’s unprinted intermediates verbatim.</p><div class="mini-flow">')
            for label,f in [('Equivalent parent NNF',frozen(rc['normalized_parent'])),('Strict scope-preserving witness formula',frozen(rc['witness_formula'])),('Displayed child',formula)]:
                parts.append('<div><strong>'+label+'</strong><div class="formula">'+math(tex(f,m))+'</div></div>')
            parts.append('</div><p>All original symbols and all earlier introductions are reserved. Existential paths, surrounding universal arguments, arities, occurrence counts and freshness are checked independently. The displayed child has a separate complete consequence certificate.</p></details>')
        parts.append('<details><summary>Exact source annotation and complete independent certificate</summary><pre>'+esc(json.dumps(dict(source=r['source'],certificate=c),indent=2))+'</pre></details></div></div>')
    parts.append('<details><summary>Complete exact E output</summary><pre>'+esc(text)+'</pre></details></article>')
    return ''.join(parts)

def raw_record(p):
    raw=p.read_bytes()
    entry=dict(sha256=sha(raw),bytes=len(raw))
    try:entry['text']=raw.decode('utf-8')
    except UnicodeDecodeError:entry['base64']=base64.b64encode(raw).decode()
    return entry

